// Snapshot-based aggregate loading
async function loadOrder(orderId: string): Promise<OrderState> {
  const snapshot = await snapshotStore.getLatest(orderId);
  if (snapshot) {
    // Snapshot found — use it as the authoritative current state
    // Delete old events since we have the snapshot (saves storage)
    await eventStore.deleteEventsBefore(orderId, snapshot.seqNum);
    return snapshot.state;
  }
  // No snapshot: fold from event 1
  const events = await eventStore.getAll(orderId);
  return events.reduce(applyEvent, initialState);
}

// Upcasting: fix a historical data error by updating stored events
async function fixOrderApprovedEvents(orderId: string): Promise<void> {
  const events = await eventStore.getAll(orderId);
  for (const event of events) {
    if (event.type === 'OrderApproved' && !event.payload.approvalThreshold) {
      event.payload.approvalThreshold = await getDefaultThreshold(event.occurredAt);
      await eventStore.update(event); // persist the fix
    }
  }
}
